    edge_map([](const RT::Edge& a, const RT::Edge& b) {
        if (a.first < b.first) return true;
        if (b.first < a.first) return false;
        if (a.second < b.second) return true;
        if (b.second < a.second) return false;
        if (a.third < b.third) return true;
        if (b.third < a.third) return false;
        return false;
    });

for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    RT::Edge edge = *eit;
    RT::Cell_handle c1 = edge.first;
    RT::Cell_handle c2 = c1->neighbor(edge.second);

    if (rt.is_infinite(c1) || rt.is_infinite(c2)) continue;

    Point p1 = c1->weighted_circumcenter();
    Point p2 = c2->weighted_circumcenter();

    double length = std::sqrt(std::pow(p1.x() - p2.x(), 2) + 
                             std::pow(p1.y() - p2.y(), 2) + 
                             std::pow(p1.z() - p2.z(), 2));

    if (length > threshold) continue;

    edge_map[edge].push_back(c1);
    edge_map[edge].push_back(c2);
}

for (const auto& entry : edge_map) {
    const RT::Edge& edge = entry.first;
    const std::vector<RT::Cell_handle>& cells = entry.second;

    if (cells.size() < 2) continue;

    std::vector<Point> polygon;
    std::set<RT::Cell_handle> unique_cells(cells.begin(), cells.end());

    for (RT::Cell_handle cell : unique_cells) {
        polygon.push_back(cell->weighted_circumcenter());
    }

    if (polygon.size() >= 3) {
        RT::Cell_handle c1 = edge.first;
        RT::Cell_handle c2 = edge.first->neighbor(edge.second);

        Point p1 = c1->weighted_circumcenter();
        Point p2 = c2->weighted_circumcenter();

        double edge_length = std::sqrt(std::pow(p1.x() - p2.x(), 2) + 
                                     std::pow(p1.y() - p2.y(), 2) + 
                                     std::pow(p1.z() - p2.z(), 2));

        result.add_face(polygon, edge_length);
    }
}

return result;
